#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<string> lines;
    string line;
    while (getline(cin, line)) lines.push_back(line);
    int n = stoi(lines[0]);
    // location -> (minute, input index, id)
    map<string, vector<array<long long, 3>>> locations;
    for (int i = 0; i < n; i++) {
        istringstream head(lines[1 + 2 * i]);
        long long id;
        string t;
        head >> id >> t;
        long long minute = stoi(t.substr(0, 2)) * 60 + stoi(t.substr(3));
        locations[lines[2 + 2 * i]].push_back({minute, i, id});
    }
    vector<pair<long long, vector<long long>>> groups;
    for (auto &[loc, rides] : locations) {
        sort(rides.begin(), rides.end());
        size_t i = 0;
        while (i < rides.size()) {
            // the earliest ungrouped ride takes up to two more rides within 10 minutes
            size_t start = i++;
            while (i < rides.size() && i - start < 3 && rides[i][0] - rides[start][0] <= 10) i++;
            long long first = LLONG_MAX;
            vector<long long> ids;
            for (size_t k = start; k < i; k++) { first = min(first, rides[k][1]); ids.push_back(rides[k][2]); }
            sort(ids.begin(), ids.end());
            groups.push_back({first, ids});
        }
    }
    sort(groups.begin(), groups.end());
    string out = to_string(groups.size()) + "\n";
    for (auto &[first, ids] : groups) {
        out += to_string(ids.size());
        for (long long id : ids) out += " " + to_string(id);
