import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        // location -> list of (minute, input index, id)
        LinkedHashMap<String, List<long[]>> locations = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            String[] head = br.readLine().trim().split("\\s+");
            long id = Long.parseLong(head[0]);
            long minute = Integer.parseInt(head[1].substring(0, 2)) * 60 + Integer.parseInt(head[1].substring(3));
            locations.computeIfAbsent(br.readLine(), k -> new ArrayList<>()).add(new long[]{minute, i, id});
        }
        List<long[]> groups = new ArrayList<>(); // [first index, size, ids...]
        for (List<long[]> rides : locations.values()) {
            rides.sort((x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
            int i = 0;
            while (i < rides.size()) {
                // the earliest ungrouped ride takes up to two more rides within 10 minutes
                int start = i++;
                while (i < rides.size() && i - start < 3 && rides.get(i)[0] - rides.get(start)[0] <= 10) i++;
                long first = Long.MAX_VALUE;
                long[] ids = new long[i - start];
                for (int k = start; k < i; k++) { first = Math.min(first, rides.get(k)[1]); ids[k - start] = rides.get(k)[2]; }
                Arrays.sort(ids);
                long[] g = new long[ids.length + 1];
                g[0] = first;
                System.arraycopy(ids, 0, g, 1, ids.length);
                groups.add(g);
            }
        }
        groups.sort((x, y) -> Long.compare(x[0], y[0]));
        StringBuilder sb = new StringBuilder();
        sb.append(groups.size()).append('\n');
        for (long[] g : groups) {
            sb.append(g.length - 1);
            for (int k = 1; k < g.length; k++) sb.append(' ').append(g[k]);
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	var lines []string
	for sc.Scan() {
		lines = append(lines, sc.Text())
	}
	n, _ := strconv.Atoi(strings.TrimSpace(lines[0]))
	type ride struct{ minute, index, id int }
	// location -> rides
	locations := map[string][]ride{}
	var order []string
	for i := 0; i < n; i++ {
		head := strings.Fields(lines[1+2*i])
		id, _ := strconv.Atoi(head[0])
		h, _ := strconv.Atoi(head[1][:2])
		mi, _ := strconv.Atoi(head[1][3:])
		loc := lines[2+2*i]
		if _, ok := locations[loc]; !ok {
			order = append(order, loc)
		}
		locations[loc] = append(locations[loc], ride{h*60 + mi, i, id})
	}
	type group struct {
		first int
		ids   []int
	}
	var groups []group
	for _, loc := range order {
		rides := locations[loc]
		sort.Slice(rides, func(a, b int) bool {
			if rides[a].minute != rides[b].minute {
				return rides[a].minute < rides[b].minute
			}
			return rides[a].index < rides[b].index
		})
		for i := 0; i < len(rides); {
			// the earliest ungrouped ride takes up to two more rides within 10 minutes
			start := i
			i++
			for i < len(rides) && i-start < 3 && rides[i].minute-rides[start].minute <= 10 {
				i++
			}
			g := group{first: rides[start].index}
			for _, r := range rides[start:i] {
				g.first = min(g.first, r.index)
				g.ids = append(g.ids, r.id)
			}
			sort.Ints(g.ids)
			groups = append(groups, g)
		}
	}
	sort.Slice(groups, func(a, b int) bool { return groups[a].first < groups[b].first })
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(groups)) + "\n")
	for _, g := range groups {
		w.WriteString(strconv.Itoa(len(g.ids)))
		for _, id := range g.ids {
			w.WriteString(" " + strconv.Itoa(id))
		}
		w.WriteByte('\n')
	}
}
